with kept_keys as (select brand, category from products except select brand, category from products where stock_qty <= 270), kept_rows as (select s.* from products s join kept_keys k on s.brand = k.brand and s.category = k.category) select brand, price, cost, launch_date, tags, case when brand rlike '^(Stark|Initech)$' then 'CORE' when brand rlike '^(Acme|Globex)$' then 'EXTENDED' else 'OTHER_ZONE' end as brand_zone from kept_rows order by brand desc nulls first;
